export function SeatStepper() {
  return <section><button>Decrease seats</button><output aria-label="Seat quantity">0</output><button>Increase seats</button></section>;
}

problems.solutionCode:
import { useState } from 'react';
export function SeatStepper() {
  const [quantity, setQuantity] = useState(0);
  return <section><button onClick={() => setQuantity((value) => Math.max(0, value - 1))}>Decrease seats</button><output aria-label="Seat quantity">{quantity}</output><button onClick={() => setQuantity((value) => value + 1)}>Increase seats</button></section>;
}

