export function CartSummary({ items: _items }: { items: { id: string; label: string; price: number }[] }) {
  return <section><ul></ul><output aria-label="Cart total">0</output></section>;
}

problems.solutionCode:
type CartItem = { id: string; label: string; price: number };
export function CartSummary({ items }: { items: CartItem[] }) {
  const total = items.reduce((sum, item) => sum + item.price, 0);
  return <section><ul>{items.map((item) => <li key={item.id}>{item.label}</li>)}</ul><output aria-label="Cart total">{total}</output></section>;
}

