problems.solutionCode:
import { useState, type FormEvent } from 'react';
export function CatalogSearch({ onSearch }: { onSearch: (query: string) => void }) {
  const [query, setQuery] = useState('');
  function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const normalized = query.trim();
    if (normalized) onSearch(normalized);
  }
  return <form onSubmit={submit}><label>Search products<input aria-label="Search products" value={query} onChange={(event) => setQuery(event.target.value)} /></label><button type="submit">Search</button></form>;
}

