import { useState, type FormEvent } from 'react';
export function CatalogSearch({ onSearch }: { onSearch: (query: string) => void }) {
  const [query, setQuery] = useState('');
  const [submittedQuery, setSubmittedQuery] = useState('');
  function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const normalized = submittedQuery.trim();
    if (normalized) onSearch(normalized);
  }
  return <form onSubmit={submit}><label>Search products<input aria-label="Search products" value={query} onChange={(event) => { setQuery(event.target.value); setSubmittedQuery(query); }} /></label><button type="submit">Search</button></form>;
}
